// A header field cached across a call that grows the vector through its address must not survive:
// the call receives `&mut v` (the slot's address, not the header word), directly, in a loop, as a
// method receiver and through a record field that holds the vector.
struct Buf { bytes: u8[], tag: u64 }
impl Buf {
    fn grow(&mut self, n: u64) {
        for i in n { self.bytes.push(u8(i % 200)); }
    }
}
fn pad<a>(out: (&a mut u8[]), align: u64) {
    if align > 1 {
        while out.len() % align != 0 {
            out.push(0);
        }
    }
}
fn widen(v: (&mut u64[]), n: u64) {
    for i in n { v.push(i); }
}
fn main() {
    mut out = u8[];
    for i in 64 { out.push(0); }
    mut off = u64[];
    a := u64[4, 8];
    d := u8[][u8[0xc3], u8[7]];
    for k in 2 {
        pad(&mut out, a[k]);
        off.push(out.len());
        out.append(view(d[k]));
    }
    println(off[1]);
    println(out.len());
    println(out[off[1]]);
    // the call in a loop, read after each call
    mut w = u64[];
    w.push(5);
    mut seen = 0;
    for r in 5 {
        before := w.len();
        widen(&mut w, r + 1);
        seen = seen + w.len() - before + w[w.len() - 1];
    }
    println(seen);
    println(w.len());
    // a method that grows a field, and the field read after it
    mut b = Buf { bytes: u8[1, 2], tag: 9 };
    l0 := b.bytes.len();
    b.grow(30);
    println(b.bytes.len() - l0);
    println(b.bytes[31]);
    // a function handed the record by `&mut`, the field read after it
    mut c = Buf { bytes: u8[], tag: 1 };
    for r in 3 {
        grow_rec(&mut c, r + 2);
        println(c.bytes.len());
    }
}
fn grow_rec(r: (&mut Buf), n: u64) {
    pad(&mut r.bytes, n);
    r.bytes.push(1);
}

