// f32 narrowing (optimize.grl `xmm_narrow`) holds a promoted slot as binary32 only when every store
// into it is a widened f32 or zero. `two: f32 := 2.0` is stored from the immediate
// $4611686018427387904 (19 digits), which the optimiser's immediate reader cannot read and reports
// as 0 - once taken for zero, so the slot was narrowed and 2.0 read back as 0.0 (meshopt's
// quadric_error_attr, which changed Abundance's abgeo mesh digests). 387 with the bug.
struct Q {
    positions: f32[],
    attributes: f32[],
    gradients: f32[],
    attribute: f32[],
    count: u64
}
fn eval(q: (&f32[]), at: u64, x: f32, y: f32, z: f32) -> f32 {
    return q[at] * x + q[at + 1] * y + q[at + 2] * z;
}
fn error_attr<a>(st: (&a Q), v: u64, t: u64) -> f32 {
    acount := st.count;
    qa := v * 11;
    x := st.positions[t * 3];
    y := st.positions[t * 3 + 1];
    z := st.positions[t * 3 + 2];
    mut r = eval(&st.attribute, qa, x, y, z);
    two: f32 := 2.0;
    for k in acount {
        a := st.attributes[t * acount + k];
        g0 := (v * acount + k) * 4;
        gx := st.gradients[g0];
        gy := st.gradients[g0 + 1];
        gz := st.gradients[g0 + 2];
        gw := st.gradients[g0 + 3];
        g: f32 := x * gx + y * gy + z * gz + gw;
        r = r + a * (a * st.attribute[qa + 10] - two * g);
    }
    return r.abs();
}
fn main() {
    mut st = Q { positions: f32[], attributes: f32[], gradients: f32[], attribute: f32[], count: 3 };
    for i in 24 {
        st.positions.push(f32(i64(i)) * 0.25);
        st.attributes.push(f32(i64(i)) * 0.5 + 1.0);
        st.attribute.push(f32(i64(i)) * 0.125);
    }
    for i in 48 {
        st.gradients.push(f32(i64(i % 7)) * 0.75 - 1.0);
    }
    mut total: f32 = 0.0;
    for v in 2 {
        for t in 3 {
            total = total + error_attr(&st, v, t);
        }
    }
    println(total);
}

