// formation: no overflow check, and a field load is one instruction (`movq 16(%rax),%rax`). Integer
// arithmetic in the same unsafe module still follows the build's overflow mode: the size `n * 8`
// overflows and aborts in a checked build.
fn field(p: u64) -> u64 {
    return raw_load(p + 16);
}
fn size(n: u64) -> u64 {
    return n * 8;
}
