use xxhash;
fn main() {
    mut buf = u8[];
    mut x: u64 = 88172645463325252;
    for i in 300 {
        x = x ^ (x << 13);
        x = x ^ (x >> 7);
        x = x ^ (x << 17);
        buf.push(x & 255);
    }
    seeds := u64[0, 1, 11400714819323198485, 18446744073709551615];
    mut acc: u64 = 0;
    for s in 4 {
        for n in 261 {
            acc = acc ^ wrapping_mul(xxhash::hash64(buf[0: n], seeds[s]), n + 1 + s * 1000);
        }
    }
    println("{} {} {}", xxhash::hash64(buf[0: 0], 0), xxhash::hash64(buf[0: 37], 1), acc);
}

