use vecs;
struct Group { depth: u64, deps: u64[] }
fn main() {
    mut gs = Group[];
    gs.push(Group { depth: 5, deps: u64[] });
    gs.push(Group { depth: 1, deps: u64[1] });
    gs.push(Group { depth: 3, deps: u64[1, 2] });
    groups := &gs;
    mut order = u64[0; groups.len()];
    for i in order.len() { order[i] = i; }
    order.sort_by(|x: &u64, y: &u64| -> bool {
        gx := &groups[*x];
        gy := &groups[*y];
        return ((u64(gx.deps.len() != 0) << 32) | (4294967295 - gx.depth)) < ((u64(gy.deps.len() != 0) << 32) | (4294967295 - gy.depth));
    });
    for i in order.len() { println("{}", order[i]); }
}

