use vecs;
use core;
fn ascending(a: &u64, b: &u64) -> bool { return *a < *b; }
fn main() {
    nums := u64[3, 8, 5, 12];
    mut counted = 0;
    c := &mut counted;
    println("count {} tested {}", nums.count(|x: &u64| -> bool { *c += 1; return *x % 2 == 0; }), counted);
    mut anyed = 0;
    a := &mut anyed;
    println("any {} tested {}", nums.any(|x: &u64| -> bool { *a += 1; return *x > 6; }), anyed);
    mut alled = 0;
    l := &mut alled;
    println("all {} tested {}", nums.all(|x: &u64| -> bool { *l += 1; return *x < 10; }), alled);
    mut found = 0;
    f := &mut found;
    println("position {} tested {}", nums.position(|x: &u64| -> bool { *f += 1; return *x == 5; }).unwrap_or(99), found);
    mut toggle = 0;
    kept := u64[1, 2, 3, 4, 5, 6].filter(|x: &u64| -> bool { toggle += 1; return toggle % 2 == 1; });
    println(kept);
    mut index = 0;
    numbered := string["a", "b", "c"].map(|w: string| -> string { index += 1; return format("{}{}", w, index); });
    println("{} {} {}", numbered[0], numbered[1], numbered[2]);
    mut steps = 0;
    s := &mut steps;
    total := u64[1, 2, 3].fold(10, |acc: u64, x: u64| -> u64 { *s += 1; return acc + x; });
    println("fold {} steps {}", total, steps);
    mut items = u64[3, 1, 2];
    mut keys = 0;
    k := &mut keys;
    items.sort_by_key(|x: &u64| -> u64 { *k += 1; return 10 - *x; });
    println("{} keys {}", items, keys);
    items.sort_by(ascending);
    println(items);
    items.sort_by(|x: &u64, y: &u64| -> bool *y < *x);
    println(items);
    mut mapped = 0;
    m := &mut mapped;
    start: u64? := Some(4);
    doubled := start.map(|x: u64| -> u64 { *m += 1; return x * 2; });
