use core;
struct Countdown { n: u64 }
impl Countdown {
    fn next(self: &mut Self) -> u64? {
        if self.n == 0 {
            return None;
        }
        self.n = self.n - 1;
        return Some(self.n);
    }
}
// Owns a vector of strings and yields owned copies.
struct Words { words: u8[][], pos: u64 }
impl Words {
    fn next(self: &mut Self) -> u8[]? {
        if self.pos < self.words.len() {
            p := self.pos;
            self.pos = p + 1;
            return Some(self.words[p].copy());
        }
        return None;
    }
}
fn main() -> u64 {
    for x in Countdown { n: 2 } {
        println(x);
    }
    mut it = Countdown { n: 6 };
    for x in &mut it {
        if x == 4 {
            continue;
        }
        if x == 2 {
            break;
        }
        println(x);
    }
    // The rest of a partly consumed iterator.
    for x in &mut it {
        println(x + 100);
    }
    mut total = 0;
    for w in Words { words: u8[][u8[1, 2], u8[3, 4, 5], u8[6]], pos: 0 } {
        total = total + w.len();
        println(w.len());
    }
    println(total);
    return 0;
}

