fn crc_table() -> u32[] {
    mut t = u32[];
    for n in 256 {
        mut c: u32 = u32(n);
        for k in 8 {
            if (c & 1) != 0 {
                c = 3988292384 ^ (c >> 1);
            } else {
                c = c >> 1;
            }
        }
        t.push(c);
    }
    return t;
}
fn squares() -> u64[] {
    mut v = u64[];
    for i in 10 {
        v.push(i * i);
    }
    return v;
}
fn magic() -> u8[] {
    return u8[71, 82, 76];
}
CRC := crc_table();
SQ := squares();
MAGIC := magic();
fn crc32(data: u8[]) -> u32 {
    table := CRC;
    mut c: u32 = 4294967295;
    for b in &data {
        c = table[u64((c ^ u32(b)) & 255)] ^ (c >> 8);
    }
    return c ^ 4294967295;
}
