use order;
interface Source {
    type Item: order::Ord;
    fn pull(self: &mut Self) -> Self::Item?;
}
struct Nums {
    left: u64,
}
impl Source for Nums {
    type Item = u64;
    fn pull(self: &mut Self) -> u64? {
        if self.left == 0 {
            return None;
        }
        self.left = self.left - 1;
        return Some(self.left * 7 % 5);
    }
}
fn largest<S: Source>(s: &mut S) -> S::Item? {
    mut best: S::Item? = None;
    while let Some(x) = s.pull() {
        match best {
            Some(b) => {
                if b < x {
                    best = Some(x);
                } else {
                    best = Some(b);
                }
            },
            None => {
                best = Some(x);
            },
        }
    }
    return best;
}
fn main() -> u64 {
    mut n = Nums { left: 6 };
    println(largest(&mut n)!);
    return 0;
}

