// The main thread's stack is the kernel's: it has no PROT_NONE page and no guard, and before
// this handler existed a program that ran it out died of SIGSEGV with empty stderr. The fault
// address is inside a stack's worth of the interrupted stack pointer, so it is named as what it
// is - `error: stack overflow`, the statement the overflowing frame was entering, status 134 -
// and not left as an unexplained signal.
fn f(n: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    return 1 + f(n - 1);
}
fn main() {
    println("before");
    println(f(100000000));
}

