// A genuine memory fault: libc's strlen dereferences a null pointer. The fault address is
// nowhere near the stack pointer, so the stack-fault handler must put the default disposition
// back and let the process die of SIGSEGV exactly as it does with no handler installed - a
// handler that reported a wild pointer as a stack overflow would hide real bugs.
extern "C" lib "c" as "strlen" fn c_strlen(s: CPtr) -> u64;
fn main() {
    println("before");
    mut n = 0;
    unsafe {
        n = c_strlen(cnull());
    }
    println(n);
}

// The same recursion as the main-stack-overflow case, a thousand frames deep: the handler
// never fires, nothing is printed on fd 2, and the program's own result is unchanged.
fn f(n: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    return 1 + f(n - 1);
}
fn main() {
    println(f(1000));
}

// Deep recursion inside a task runs into the guard page at the bottom of its stack. The fault is
// recognised as a task-stack overflow and reported once, by name, with status 134 - not as a silent
// write into the neighbouring mapping and not as an unexplained SIGSEGV.
fn deep(n: u64, unused: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    return deep(n - 1, 0) + 1;
}
fn body<s>(sc: (&s Scope<u64>), base: u64) -> u64 {
    t := spawn(sc, 1000000, deep);
    return join(t);
}
fn main() {
    println("before");
    println(task_scope(0, body));
}

