// A `&dyn` pair built in a loop, copied, passed to a function and returned.
interface Shape {
    fn area(self: &Self) -> u64;
    fn grow(self: &mut Self, by: u64) -> unit;
}
struct Sq {
    side: u64,
}
struct Ci {
    r: u64,
}
impl Shape for Sq {
    fn area(self: &Self) -> u64 {
        return self.side * self.side;
    }
    fn grow(self: &mut Self, by: u64) -> unit {
        self.side = self.side + by;
        return ();
    }
}
impl Shape for Ci {
    fn area(self: &Self) -> u64 {
        return 3 * self.r * self.r;
    }
    fn grow(self: &mut Self, by: u64) -> unit {
        self.r = self.r + by;
        return ();
    }
}
fn round(s: &dyn Shape) -> u64 {
    return s.area();
}
fn as_shape(v: &Sq) -> &dyn Shape {
    return v;
}
fn main() -> u64 {
    mut q = Sq { side: 1 };
    mut c = Ci { r: 2 };
    mut total = 0;
    for i in 10 {
        mut d: &mut dyn Shape = &mut q;
        d.grow(1);
        e: &dyn Shape = &q;
        same := e;
        total = total + round(same);
        total = total + round(&c);
        total = total + as_shape(&q).area();
    }
    println("{} {}", total, q.side);
    return 0;
}

