module stdmap_model;

use core;
use order;
use btree;

// A reference model: the same pairs, kept sorted, with the same operations.
struct Model {
    keys: u64[],
    values: u64[]
}

fn model_insert(m: (&mut Model), key: u64, value: u64) {
    mut lo = 0;
    mut hi = m.keys.len();
    while lo < hi {
        mid := lo + (hi - lo) / 2;
        if m.keys[mid] < key {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if lo < m.keys.len() {
        if m.keys[lo] == key {
            m.values[lo] = value;
            return ();
        }
    }
    m.keys.insert(lo, key);
    m.values.insert(lo, value);
    return ();
}

fn model_remove(m: (&mut Model), key: u64) -> u64? {
    mut i = 0;
    while i < m.keys.len() {
        if m.keys[i] == key {
            m.keys.remove(i);
            return Some(m.values.remove(i));
        }
        i += 1;
    }
    return None;
}

fn model_get(m: (&Model), key: u64) -> u64? {
    mut i = 0;
    while i < m.keys.len() {
        if m.keys[i] == key {
            return Some(m.values[i]);
        }
        i += 1;
    }
    return None;
}

// A permutation of 0..1000 (7919 is coprime with 1000), so insertion order is not key order.
fn probe(i: u64) -> u64 {
    return (i * 7919 + 13) % 1000;
}

// The map must walk exactly the model's pairs, in the model's order.
fn check_order(map: (&btree::BTreeMap<u64, u64>), model: (&Model)) -> u64 {
    assert(map.len() == model.keys.len());
    mut seen = 0;
    mut prior = 0;
    mut started = 0;
    for pair in map.iter() {
        key := pair.0;
        value := pair.1;
        if started == 1 {
            assert(prior < *key);
        }
        started = 1;
        prior = *key;
        assert(*key == model.keys[seen]);
        assert(*value == model.values[seen]);
        seen += 1;
    }
    assert(seen == model.keys.len());
    return seen;
}

fn main() {
    mut map = btree::new<u64, u64>();
    mut model = Model { keys: u64[], values: u64[] };
    assert(map.is_empty());
    for i in 1000 {
        key := probe(i);
        value := key * 3 + 1;
        map.insert(key, value);
        model_insert(&mut model, key, value);
    }
    assert(map.len() == 1000);
    println(check_order(&map, &model));
    // Every lookup answers the model's value; a key above the range misses.
    for i in 1000 {
        key := probe(i);
        want := model_get(&model, key)!;
        if let Some(got) = map.get(&key) {
            assert(*got == want);
        } else {
            assert(false);
        }
        assert(map.contains_key(&key));
    }
    assert(!map.contains_key(&1000));
    match map.get(&1000) {
        Some(v) => { assert(false); },
        None => { println(0); }
    }
    // first and last are the smallest and largest keys, 0 and 999.
    if let Some(top) = map.first() {
        if let Some(bottom) = map.last() {
            println(*top.0 * 1000 + *bottom.0);
        } else {
            assert(false);
        }
    } else {
        assert(false);
    }
    // get_mut writes through to the stored value.
    match map.get_mut(&7) {
        Some(v) => { *v = 777; },
        None => { assert(false); }
    }
    model_insert(&mut model, 7, 777);
    if let Some(seven) = map.get(&7) {
        println(*seven);
    } else {
        assert(false);
    }
    // Overwriting a key answers the old value and keeps the count.
    match map.insert(9, 99) {
        Some(old) => { println(old); },
        None => { assert(false); }
    }
    model_insert(&mut model, 9, 99);
    assert(map.len() == 1000);
    // get_or_insert keeps a stored value and inserts a missing one.
    mut slot = map.get_or_insert(9, 1);
    *slot = 99;
    fresh := map.get_or_insert(1000, 500);
    println(*fresh);
    map.insert(1000, 500);
    model_insert(&mut model, 1000, 500);
    println(check_order(&map, &model));
    // Removing half the keys in a second order leaves the tree ordered and complete.
    for i in 500 {
        key := probe(i * 2 + 1);
        removed := map.remove(&key);
        expected := model_remove(&mut model, key);
        match removed {
            Some(v) => {
                held := expected!;
                assert(held == v);
            },
            None => {
                assert(expected.is_none());
            }
        }
    }
    println(check_order(&map, &model));
    // Range walks exactly the window lo..hi, in order.
    mut window = 0;
    for pair in map.range(&200, &300) {
        key := pair.0;
        assert(*key >= 200);
        assert(*key < 300);
        want := model_get(&model, *key)!;
        assert(*pair.1 == want);
        window += 1;
    }
    mut expected_window = 0;
    for i in model.keys.len() {
        if model.keys[i] >= 200 {
            if model.keys[i] < 300 {
                expected_window += 1;
            }
        }
    }
    println(window == expected_window);
    // Removing every remaining key empties the tree.
    for i in model.keys.len() {
        key := model.keys[model.keys.len() - 1 - i];
        assert(map.remove(&key).is_some());
    }
    model.keys.clear();
    model.values.clear();
    assert(map.is_empty());
    println(map.len());
    match map.first() {
        Some(pair) => { assert(false); },
        None => { println(1); }
    }
}

