use fs;
use core;
use strings;

// A real tree in the case's own scratch directory: create, write, read, stat, walk, list, rename,
// copy and remove, with every step observed.
fn main(){
    match fs::remove_dir_all(view("tree")) {
        e: fs::Error => {},
        _ => {}
    }
    fs::create_dir_all(view("tree/a/b"))!;
    fs::create_dir_all(view("tree/c"))!;
    fs::write(view("tree/a/b/one.txt"), view("hello"))!;
    fs::write(view("tree/a/two.txt"), view("second"))!;
    fs::write_atomic(view("tree/c/atomic.txt"), view("all at once"))!;
    println(fs::read_text(view("tree/c/atomic.txt"))!);
    md := fs::metadata(view("tree/a/b/one.txt"))!;
    println(md.size());
    println(md.is_file());
    println(md.is_dir());
    println(md.permissions() != 0);
    println(md.modified.unix_seconds() > 1600000000);
    entries := fs::walk(view("tree"), fs::walk_options())!;
    mut i = 0;
    while i < entries.len() {
        println(entries[i].path());
        i = i + 1;
    }
    names := fs::list_dir(view("tree/a"))!;
    println(names.len());
    println(names[0].text());
    fs::rename(view("tree/a/two.txt"), view("tree/a/renamed.txt"))!;
    println(fs::exists(view("tree/a/renamed.txt")));
    println(fs::exists(view("tree/a/two.txt")));
    fs::copy(view("tree/a/b/one.txt"), view("tree/c/copy.txt"))!;
    println(fs::read_text(view("tree/c/copy.txt"))!);
    fs::remove_dir_all(view("tree"))!;
    println(fs::exists(view("tree")));
    match fs::read_text(view("tree/one.txt")) {
        e: fs::Error => { println(e.show()); },
        t: string => { println(t); }
    }
    println("done");
}

use fs;
use core;

// Every path operation is lexical: these answers need no file to exist.
fn main(){
    p := fs::path(view("a/./b/../c//d/"));
    println(p.show());
    println(p.is_absolute());
    println(p.parent()!.show());
    println(p.file_name()!.text());
    println(p.file_stem()!.text());
    q := fs::path(view("archive.tar.gz"));
    println(q.extension()!.text());
    r := fs::path(view(".bashrc"));
    println(r.extension() == None);
    root := fs::path(view("/usr//local/../share/./zoneinfo/"));
    println(root.normalize().show());
    println(root.normalize().parent()!.show());
    joined := fs::path(view("/tmp")).join(view("x/y.txt"));
    println(joined.show());
    println(fs::path(view("/tmp")).join(view("/etc/hosts")).show());
    here := fs::path(view(".")).canonicalize()!;
    println(here.is_absolute());
    println(here.file_name() != None);
    println(fs::path(view("")).is_absolute());
    println(fs::path(view("..")).normalize().show());
    println("done");
}

use fs;
use core;
use io;
use strings;

// Text that is not UTF-8 is refused with the offset of the first ill-formed byte, a file handle is
// closed exactly once, and a name that is not ASCII is a name like any other.
fn main(){
    raw := u8[111, 107, 255, 254]; // "ok" then two bytes that are not UTF-8
    fs::write(view("bad.txt"), view(raw))!;
    match fs::read_text(view("bad.txt")) {
        e: fs::Error => { println(e.show()); },
        t: string => { println(t); }
    }
    match fs::metadata(view("missing.txt")) {
        e: fs::Error => { println(e.is_not_found()); },
        m: fs::Metadata => { println(false); }
    }
    match fs::list_dir(view("missing")) {
        e: fs::Error => { println(e.is_not_found()); },
        names: u8[][] => { println(false); }
    }
    match fs::read_text(view("missing.txt")) {
        e: fs::Error => { println(e.show()); },
        t: string => { println(t); }
    }
    mut writer = fs::create(view("handles.txt"))!;
    writer.write(view("first line"))!;
    writer.close()!;
