use fs;
use core;

// The walker's symbolic-link policy: a link is an entry of its own; following enters the target,
// and a link back to an ancestor is not entered again - so the walk always ends.
fn main(){
    fs::create_dir_all(view("real/inner"))!;
    fs::write(view("real/inner/file.txt"), view("x"))!;
    fs::symlink(view("real"), view("alias"))!;
    fs::symlink(view(".."), view("real/inner/up"))!;
    plain := fs::walk(view("real"), fs::walk_options())!;
    println(plain.len());
    mut links = 0;
    mut i = 0;
    while i < plain.len() {
        if plain[i].is_symlink() {
            links = links + 1;
        }
        i = i + 1;
    }
    println(links);
    following := fs::follow_links(fs::walk_options(), true);
    followed := fs::walk(view("real"), following)!;
    println(followed.len());
    mut files = 0;
    i = 0;
    while i < followed.len() {
        if followed[i].is_file() {
            files = files + 1;
        }
        i = i + 1;
    }
    println(files);
    target := fs::metadata(view("alias/inner/file.txt"))!;
    println(target.is_file());
    link_md := fs::symlink_metadata(view("alias"))!;
    println(link_md.is_symlink());
    fs::remove_dir_all(view("real"))!;
    fs::remove_file(view("alias"))!;
    println(fs::exists(view("real")));
    println("done");
}

use process;
use core;
use strings;

// A child is started from an argument vector, its two output streams are captured separately, and
// how it ended is a value: an exit code, or the signal that killed it.
fn argv2(program: string, argument: string) -> u8[][] {
    mut args = u8[][];
    args.push(view(program).copy());
    args.push(view(argument).copy());
    return args;
}
fn main(){
    mut ok = argv2("/bin/sh", "-c");
    mut args = u8[][];
    mut i = 0;
    while i < ok.len() {
        args.push(ok[i].copy());
        i = i + 1;
    }
    args.push("echo out; echo err 1>&2; exit 3".copy());
    captured := process::run(&args)!;
    println(captured.code());
    println(captured.succeeded());
    println(captured.out());
    println(captured.err());
    println(captured.is_truncated());
    println(captured.show_status());
    mut killed_args = u8[][];
    killed_args.push("/bin/sh".copy());
    killed_args.push("-c".copy());
    killed_args.push("kill -9 $$".copy());
    killed := process::run(&killed_args)!;
    println(killed.signal());
    println(killed.show_status());
    println(killed.code());
    mut echo_args = u8[][];
    echo_args.push("/bin/echo".copy());
    echo_args.push("hello world".copy());
    plain := process::spawn(&echo_args)!;
    println(plain.id() > 0);
    status := plain.wait()!;
    println(status.code());
    println(status.is_success());
    println(status.show());
    mut missing = u8[][];
    missing.push("/nonexistent/grail-test-program".copy());
    match process::run(&missing) {
        e: process::Error => { println(e.show()); },
        out: process::Output => { println(out.code()); }
    }
    println("done");
}

