use utf8;
use core;
use io;
use strings;

// A validated value: construction refuses ill-formed bytes with the offset, every operation
// preserves validity, and the bytes come back out without a copy.
fn main(){
    good := utf8::from_bytes(view("g\u{e4}ns"))!;
    println(good.len());
    println(good.char_count());
    println(good.show());
    match utf8::from_bytes(view("ab")) {
        e: utf8::Error => { println(e.show()); },
        v: utf8::Utf8String => { println(v.show()); }
    }
    mut broken = u8[];
    broken.push(97);
    broken.push(197);
    broken.push(44);
    match utf8::from_bytes(view(broken)) {
        e: utf8::Error => { println(e.show()); },
        v: utf8::Utf8String => { println(v.show()); }
    }
    // slices at character boundaries, and one that is not
    left := good.slice_chars(0, 1)!;
    println(left.show());
    match good.slice_chars(1, 2) {
        e: utf8::Error => { println(e.show()); },
        v: utf8::Utf8String => { println(v.show()); }
    }
    whole := good.slice_chars(0, good.len())!;
    println(whole.same(&good));
    // concatenation and replacement preserve the invariant
    joined := left.concat(&good);
    println(joined.show());
    replaced := good.replace(&left, &utf8::from_text("x".text()));
    println(replaced.show());
    println(joined.same(&joined.copy()));
    // ASCII case mapping is total, anything else is refused by code point
    println(utf8::from_text("Hello".text()).to_upper()!.show());
    println(utf8::from_text("Hello".text()).to_ascii_lower().show());
    match good.to_upper() {
        e: utf8::Error => { println(e.show()); },
        v: utf8::Utf8String => { println(v.show()); }
    }
    // every code point of valid text decodes: no U+FFFD substitution can occur
    mut codepoints = u64[];
    for c in good.chars() {
        codepoints.push(u64(c));
    }
    println(codepoints.len());
    println(codepoints[1]);
    // the view is the bytes, not a copy
    raw := good.as_bytes();
    println(raw.len());
    println(raw.is_utf8());
    // the unchecked hatch, used where the bytes are known good
    mut hatched = utf8::empty();
    unsafe {
        hatched = utf8::from_unchecked(view("safe"));
    }
    println(hatched.show());
    println("done");
}

use utf8;
use core;
use strings;

// The invariant, checked by construction from arbitrary bytes: a deterministic pseudo-random walk
// over 10,000 mutations of a valid string. Every value the constructor accepts must re-validate,
// and every refusal must name an offset that is really there.
fn next(slot: (&mut u64)) -> u64 {
    // xorshift64: deterministic, and no table to keep in step.
    mut x = exchange(slot, 0);
    x = x ^ wrapping_mul(x, 8192);
    x = x ^ (x / 131072);
    x = x ^ wrapping_mul(x, 32);
    exchange(slot, x);
    return x;
}
fn main(){
    mut seed = 88172645463325252;
    base := utf8::from_text("Grail \u{4e16}\u{754c} caf\u{e9} \u{1f600}".text());
    mut accepted = 0;
    mut refused = 0;
    mut round = 0;
    while round < 10000 {
        mut mutant = base.as_bytes().copy();
        roll := next(&mut seed) % 4;
        at := next(&mut seed) % (mutant.len() + 1);
        if roll == 0 {
            mutant.push(u8(next(&mut seed) % 256));
        } else {
            if roll == 1 {
                if mutant.len() != 0 {
                    mutant.pop()!;
                }
            } else {
                if mutant.len() != 0 {
                    index := next(&mut seed) % mutant.len();
                    mutant[index] = u8(next(&mut seed) % 256);
                }
            }
        }
        match utf8::from_bytes(view(mutant)) {
            e: utf8::Error => {
                refused = refused + 1;
                // the offset is inside the byte string the constructor was handed
                mut check_offset = 0;
                match e {
                    InvalidUtf8(at) => { check_offset = at; },
                    _ => { check_offset = 0; }
                }
                if check_offset > mutant.len() {
                    println("offset out of range");
                    return ();
                }
            },
            value: utf8::Utf8String => {
                accepted = accepted + 1;
                if !value.as_bytes().is_utf8() {
                    println("accepted invalid UTF-8");
                    return ();
                }
                // re-validation through the checked constructor agrees
                again := utf8::from_bytes(value.as_bytes())!;
                if !again.same(&value) {
                    println("re-validation disagreed");
                    return ();
                }
                if value.char_count() == 0 {
                    println("char count lost");
                    return ();
                }
            }
        }
        round = round + 1;
    }
    println(accepted > 0);
    println(refused > 0);
    println(accepted + refused == 10000);
    println("done");
}

