// Facts about the machine's own tzdata, pinned where the files are there and skipped cleanly where
// they are not: Europe/Berlin across both 2026 DST changes, and Australia/Lord_Howe, whose saving
// is thirty minutes rather than an hour.
fn main(){
    mut loaded = 0;
    if fs::exists(view("/usr/share/zoneinfo/Europe/Berlin")) {
        zone := tz::load(view("Europe/Berlin"))!;
        println(zone.name().len());
        println(zone.transition_count() > 100);
        println(zone.has_footer());
        println(zone.offset_at(1767222000));
        println(zone.abbreviation_at(1767222000).text());
        println(zone.offset_at(1780000000));
        println(zone.abbreviation_at(1780000000).text());
        // 2026-10-25 02:30 happens twice, an hour apart
        twice := tz::local(2026, 10, 25, 2, 30, 0);
        match zone.from_local(&twice) {
            Ambiguous(pair) => {
                println(pair.earlier());
                println(pair.later());
            },
            Unique(instant) => { println("unique"); },
            Skipped(gap) => { println("skipped"); }
        }
        // 2026-03-29 02:30 never happens
        missing := tz::local(2026, 3, 29, 2, 30, 0);
        match zone.from_local(&missing) {
            Skipped(gap) => { println(gap.seconds()); },
            Unique(instant) => { println("unique"); },
            Ambiguous(pair) => { println("ambiguous"); }
        }
        winter := tz::local(2026, 1, 1, 12, 0, 0);
        println(zone.to_local(zone.instant_of(&winter)!).show());
        loaded = loaded + 1;
    } else {
        println("no system zoneinfo");
    }
    if fs::exists(view("/usr/share/zoneinfo/Australia/Lord_Howe")) {
        lord := tz::load(view("Australia/Lord_Howe"))!;
        println(lord.offset_at(1767222000));
        println(lord.abbreviation_at(1767222000).text());
        println(lord.offset_at(1780000000));
        println(lord.abbreviation_at(1780000000).text());
        loaded = loaded + 1;
    } else {
        println("no Lord Howe");
    }
    if fs::exists(view("/usr/share/zoneinfo/UTC")) {
        utc := tz::load(view("UTC"))!;
        println(utc.offset_at(0));
        println(utc.abbreviation_at(0).text());
        loaded = loaded + 1;
    }
    println(loaded > 0);
    // a name may not escape the zone directory, and a missing zone is reported
    match tz::load(view("../etc/passwd")) {
        e: tz::Error => { println(e.show()); },
        z: tz::TimeZone => { println("loaded"); }
    }
    match tz::load(view("Europe/NotAZone")) {
