module resgen;
use result;
use core;

// Both standard shapes, both arms. `Result` carries its failure in `Err`; `Option` is the type `T?`
// names, so `Some`/`None` and `u64?` are the same values.
fn halve(n: u64) -> result::Result<u64, string> {
    if n % 2 != 0 {
        return result::Result::Err("odd".text());
    }
    return result::Result::Ok(n / 2);
}
fn maybe(n: u64) -> u64? {
    if n > 3 {
        return None;
    }
    return Some(n);
}
fn main() {
    match halve(8) {
        Ok(v) => { println("ok {}", v); },
        Err(e) => { println("err {}", e); }
    }
    match halve(9) {
        Ok(v) => { println("ok {}", v); },
        Err(e) => { println("err {}", e); }
    }
    match maybe(2) {
        Some(v) => { println("some {}", v); },
        None => { println("none"); }
    }
    match maybe(7) {
        Some(v) => { println("some {}", v); },
        None => { println("none"); }
    }
    a := halve(4);
    println("{}", a.is_ok());
    println("{}", a.map(|n: u64| n * 3).unwrap_or(0));
    b := result::Option::Some(5);
    println("{}", b.is_some());
    println("{}", b.map(|n: u64| n + 1).unwrap_or(0));
    c := halve(3);
    println("{}", c.unwrap_or(7));
}

module resgen;
use result;
use core;

// Two members with names the compiler has never heard of: the success is the first declared variant,
// the failure the second, and `?` still propagates. `Out2` declares them the other way round to show
// that position - not the payload type - decides.
enum Out<V, F> { Good(V), Bad(F) }
enum Out2<V, F> { Bad(F), Good(V) }

fn inner(n: u64) -> Out<u64, string> {
    if n == 0 {
        return Out::Bad("zero".text());
    }
    return Out::Good(n);
}
fn outer(n: u64) -> Out<u64, string> {
    v := inner(n)?;
    return Out::Good(v + 1);
}
fn reversed(n: u64) -> Out2<u64, string> {
    if n == 0 {
        return Out2::Bad("zero".text());
    }
    return Out2::Good(n);
}
fn main() {
    match outer(2) {
        Good(v) => { println("good {}", v); },
        Bad(e) => { println("bad {}", e); }
    }
    match outer(0) {
        Good(v) => { println("good {}", v); },
        Bad(e) => { println("bad {}", e); }
    }
    match reversed(4) {
        Good(v) => { println("good {}", v); },
        Bad(e) => { println("bad {}", e); }
    }
}

module resgen;
use result;
use core;

// A payload that is itself a generic instance, a payload that is an optional value, and a payload
// that is a reference: each is an ordinary substituted field type, and the reference keeps its loan.
fn inner(n: u64) -> result::Result<u64, string> {
    if n == 0 {
        return result::Result::Err("zero".text());
    }
    return result::Result::Ok(n);
}
fn nested(n: u64) -> result::Result<result::Result<u64, string>, string> {
    if n > 9 {
        return result::Result::Err("too big".text());
    }
    return result::Result::Ok(inner(n));
}
fn wrapped(n: u64) -> result::Result<u64?, string> {
    if n > 9 {
        return result::Result::Err("too big".text());
    }
    if n == 0 {
        return result::Result::Ok(None);
    }
    return result::Result::Ok(Some(n));
}
fn first<a>(items: (&a u64[])) -> result::Result<&a u64, string> {
    if items.len() == 0 {
        return result::Result::Err("empty".text());
    }
    return result::Result::Ok(&items[0]);
}
fn main() {
    match nested(3) {
        Ok(r) => {
            match r {
                Ok(v) => { println("deep {}", v); },
                Err(e) => { println("deep err {}", e); }
            }
        },
        Err(e) => { println("outer err {}", e); }
    }
    match nested(5) {
