// `?` through three layers, once over the generic enum and once over a two-member union, ending at
// different success types: the failure type is what every layer agrees on.
fn read_number(text: (&[u8])) -> u64 |? string {
    if text.len() == 0 {
        return "empty".text();
    }
    mut n = 0;
    for b in text {
        if b < 48 || 57 < b {
            return "not a number".text();
        }
        n = n * 10 + u64(b - 48);
    }
    return n;
}
fn third(value: u64) -> u64 |? string {
    if value == 0 {
        return "zero".text();
    }
    return value;
}
fn second(text: (&[u8])) -> u64 |? string {
    n := read_number(text)?;
    return third(n)?;
}
fn first(text: (&[u8])) -> bool | u64 |? string {
    v := second(text)?;
    return v > 10;
}
fn stage3(n: u64) -> result::Result<u64, string> {
    if n == 0 {
        return result::Result::Err("zero".text());
    }
    return result::Result::Ok(n);
}
fn stage2(n: u64) -> result::Result<u64, string> {
    v := stage3(n)?;
    return result::Result::Ok(v + 1);
}
fn stage1(n: u64) -> result::Result<u64, string> {
    v := stage2(n)?;
    return result::Result::Ok(v * 10);
}
fn main() {
    match first(view("42")) {
        bool(b) => { println("bool {}", b); },
        u64(n) => { println("num {}", n); },
        string(e) => { println("err {}", e); },
    }
    match first(view("0")) {
        bool(b) => { println("bool {}", b); },
        u64(n) => { println("num {}", n); },
        string(e) => { println("err {}", e); },
