    match first(view("x1")) {
        bool(b) => { println("bool {}", b); },
        u64(n) => { println("num {}", n); },
        string(e) => { println("err {}", e); },
    }
    match stage1(4) {
        Ok(v) => { println("chain {}", v); },
        Err(e) => { println("chain err {}", e); }
    }
    match stage1(0) {
        Ok(v) => { println("chain {}", v); },
        Err(e) => { println("chain err {}", e); }
    }
