module ffin_c_definition_pointer_length;

// The pair C actually passes, spelled as two parameters: a pointer and a length. The body copies
// them with `cslice` inside `unsafe`, which is the documented way to read C memory, so an exported
// C function keeps a working way to receive a buffer now that a byte view parameter is refused.
extern "C" fn sum_bytes(p: CPtr, n: u64) -> u64 {
    mut total: u64 = 0;
    unsafe {
        bytes := cslice(u8, p, n);
        for i in bytes.len() {
            total = total + u64(bytes[i]);
        }
    }
    return total;
}

// The pair in the middle of the list, with a word after it: (a, pointer, length, z) is four argument
// words, and the fourth must still arrive as the fourth.
extern "C" fn tagged(a: u64, p: CPtr, n: u64, z: u64) -> u64 {
    mut total: u64 = 0;
    unsafe {
        bytes := cslice(u8, p, n);
        for i in bytes.len() {
            total = total + u64(bytes[i]);
        }
    }
    return a * 1000000 + total * 100 + z;
}

extern "C" as "sum_bytes" fn csum(p: CPtr, n: u64) -> u64;
extern "C" as "tagged" fn ctagged(a: u64, p: CPtr, n: u64, z: u64) -> u64;

fn main() -> u64 {
