use host;
// Every inline check kind, failing inside a task so the failure is contained and its message can
// be printed: built with --release (the LLVM backend), whose stream has no site table.
fn overflow(n: u64, base: u64) -> u64 { a: u64 := 18446744073709551615 - base; return a + n; }
fn negative(n: u64, base: u64) -> u64 { x: i64 := 0 - i64(n); return u64(x); }
fn divide(n: u64, base: u64) -> u64 { return base / (n - 1); }
fn unwrap(n: u64, base: u64) -> u64 { mut v = u64[]; if n == 2 { v.push(1); } return v.pop()!; }
fn index8(n: u64, base: u64) -> u64 { v := u64[10, 20, 30]; return v[n + 5]; }
fn index4(n: u64, base: u64) -> u64 { v := f32[1.0, 2.0]; s := &v[0: 2]; return u64(s[n + 3]); }
fn asserted(n: u64, base: u64) -> u64 { assert(n == 2); return 0; }
fn report<s>(sc: (&s Scope<u64>), f: fn(u64, u64) -> u64) -> unit {
    t := spawn(sc, 1, f);
    match try_join(t) {
        v: u64 => { println(v); },
        e: TaskFailure => { host::print(e.message); host::print(view("\n")); },
    }
}
fn body<s>(sc: (&s Scope<u64>), base: u64) -> u64 {
    report(sc, overflow);
    report(sc, negative);
    report(sc, divide);
    report(sc, unwrap);
    report(sc, index8);
    report(sc, index4);
    report(sc, asserted);
    return 0;
}
fn main() { task_scope(0, body); }

