struct Row {
    id: u64,
    cells: u64[]
}
fn build(i: u64) -> Row[] {
    mut rows = Row[];
    for k in 40 {
        mut cells = u64[];
        for c in (i + k) % 13 + 1 {
            cells.push(i * 1000 + k + c);
        }
        rows.push(Row { id: k, cells: cells });
    }
    return rows;
}
fn main() {
    mut total = 0;
    for round in 60 {
        made := pool::run<Row[]>(16, |i: u64| -> Row[] build(i + round));
        for i in made.len() {
            for k in made[i].len() {
                total += made[i][k].cells.len() + made[i][k].cells[0] % 7;
            }
        }
    }
    println(total);
}

use host;
fn read(n: u64, unused: u64) -> u64 {
    text := host::read_file("/proc/self/stat");
    mut kept = u64[];
    for i in n % 9 + 1 {
        kept.push(text.len() + i);
    }
    return kept.len() / kept.len();
}
fn body<s>(sc: (&s Scope<u64>), base: u64) -> u64 {
    mut many = Task<u64>[];
    for i in 64 {
        many.push(spawn(sc, i, read));
    }
    mut total = 0;
    while many.len() != 0 {
        total += join(many.pop()!);
    }
    return total;
}
fn main() {
    println(task_scope(0, body));
}

