// f32 rounding, differentially: the hardware narrowing every backend uses against the integer
// reference below (the algorithm of `rt_f32_round`), over edge words and a pseudo-random sweep of
// binary64 bit patterns. Non-NaN results must agree bit for bit; a NaN must come out a NaN, and
// its payload is not promised.
fn reference(v: u64) -> u64 {
    sign := v & 9223372036854775808;
    e := (v / 4503599627370496) & 2047;
    if e == 2047 { return v; }
    if e == 0 { return sign; }
    m := (v & 4503599627370495) + 4503599627370496;
    mut shift = 29;
    if e < 897 { shift = 926 - e; }
    if 53 < shift { return sign; }
    q0 := m >> shift;
    rem := m - (q0 << shift);
    half := 1 << (shift - 1);
    mut q = q0;
    if (half < rem) || ((rem == half) && ((q0 & 1) == 1)) { q += 1; }
    if q == 0 { return sign; }
    mut top = 0;
    while (1 << (top + 1)) < q + 1 { top += 1; }
    biased := e - 52 + shift + top;
    if 1150 < biased { return sign + 9218868437227405312; }
    return sign + biased * 4503599627370496 + ((q << (52 - top)) - 4503599627370496);
}
fn is_nan_word(w: u64) -> bool {
    return (((w / 4503599627370496) & 2047) == 2047) && ((w & 4503599627370495) != 0);
}
fn check(w: u64) -> u64 {
    d := f64_from_bits(w);
    r: f32 := f32(d);
    got := bits(f64(r));
    want := reference(w);
    if is_nan_word(w) {
        if is_nan_word(got) { return 0; }
        return 1;
    }
    if got == want { return 0; }
    return 1;
}
fn main() {
    mut bad = 0;
    mut count = 0;
    // Every exponent, with mantissas that sit on, just under and just over each rounding boundary.
    mantissas := u64[0, 1, 268435455, 268435456, 268435457, 536870911, 536870912, 536870913, 805306368,
        805306369, 4503599627370495, 4503599090499584, 4503599358935040, 2251799813685248, 1125899906842624];
    for e in 2048 {
        for k in mantissas.len() {
            w := e * 4503599627370496 + mantissas[k];
            bad += check(w);
            bad += check(w + 9223372036854775808);
            count += 2;
        }
    }
    // A sweep of arbitrary words, and of words whose exponent lies in the f32 range and below it,
    // where ties and subnormal results are.
    mut x = 88172645463325252;
    for i in 1000000 {
        x = x ^ (x << 13);
        x = x ^ (x >> 7);
        x = x ^ (x << 17);
        bad += check(x);
        e := 860 + (x >> 40) % 330;
        w := (x & 9227875636482146303) + e * 4503599627370496;
        bad += check(w);
        bad += check(w & 18446744073172680704);
        bad += check((w & 18446744073172680704) + 268435456);
        count += 4;
    }
    println(count);
    println(bad);
}

// Every float operation, comparison, negation, abs, sqrt and int<->float conversion, at both widths,
// over edge values: zeros of both signs, subnormals, the largest finite values, infinities, NaN and
// the values around 2^24, 2^53, 2^63 and 2^64. Each line is a fold of the result bits of one
// operation over the whole table. The native backend computes these in line and the LLVM backend
// through the lifter, so this output is where the two are held together (native on x86-64, aarch64
// and riscv64; LLVM on x86-64). A NaN result folds as one fixed word: its payload is not promised.
fn fold(h: u64, w: u64) -> u64 {
    mut x = h ^ w;
    x = x ^ (x << 13);
    x = x ^ (x >> 7);
    x = x ^ (x << 17);
    return x;
}
fn w64(x: f64) -> u64 {
    if x != x { return 7; }
    return bits(x);
}
fn w32(x: f32) -> u64 {
    if x != x { return 7; }
    return f32_bits(x);
}
fn flag(b: bool) -> u64 {
    if b { return 1; }
    return 2;
}
fn show(name: &[u8], h: u64) {
    println("{} {}", name, h);
}
fn doubles() -> f64[] {
    words := u64[0, 9223372036854775808, 1, 4503599627370495, 4503599627370496, 4607182418800017408,
        13830554455654793216, 4602678819172646912, 4609434218613702656, 4613937818241073152,
        4715268809856909312, 4715268810393780224, 4715268810930651136, 4845873199050653695,
        4845873199050653696, 4845873199050653697, 4890909195324358656, 4895412794951729152,
        9218868437227405311, 18442240474082181119, 9218868437227405312, 18442240474082181120,
        9221120237041090560, 4591870180066957722, 39178067011604550, 9176801472524566770,
        4890909195324358657, 4841369599423283200, 13839561654909534208];
    mut out = f64[];
    for i in words.len() { out.push(f64_from_bits(words[i])); }
    return out;
}
fn singles() -> f32[] {
    words := u64[0, 2147483648, 1, 8388607, 8388608, 1065353216, 3212836864, 1056964608, 1069547520,
        1077936128, 1266679807, 1266679808, 1266679809, 1593835520, 1602224128, 2139095039, 4286578687,
        2139095040, 4286578688, 2143289344, 1036831949, 1258291200, 3225419776, 1593835521];
    mut out = f32[];
    for i in words.len() { out.push(f32_from_bits(words[i])); }
