// f32 values held as binary32 in SSE registers (optimize.grl `xmm_narrow`): a copy from one f32
// local to another, an accumulator that starts at zero, a mix of f32 and f64 in one expression, and
// a result read as f64 must all print what they print with every value widened.
fn scale_add(x: (&mut [f32]), y: (&[f32]), a: f32) -> unit {
    n := x.len();
    mut i = 0;
    while i < n {
        x[i] = x[i] * a + y[i];
        i += 1;
    }
}
fn dot(x: (&[f32]), y: (&[f32])) -> f32 {
    mut s: f32 = 0.0;
    for i in x.len() {
        s = s + x[i] * y[i];
    }
    return s;
}
fn main() {
    mut x = f32[];
    mut y = f32[];
    mut xv: f32 = 0.0;
    mut yv: f32 = 0.0;
    for i in 1000 {
        x.push(xv);
        y.push(yv);
        prev := xv;
        xv = prev + 0.5;
        if 3.0 < xv { xv = 0.0; }
        yv = yv + 0.25;
        if 1.0 < yv { yv = 0.0; }
    }
    for pass in 20 {
        scale_add(&mut x[0: 1000], &y[0: 1000], 0.999);
    }
    mut sum: f64 = 0.0;
    mut wide: f64 = 0.0;
    for i in 1000 {
        sum = sum + f64(x[i]);
        t := x[i] * 1.5;
        wide = wide + f64(t) / 3.0;
    }
    println(sum);
    println(wide);
    println(dot(&x[0: 1000], &y[0: 1000]));
    a: f32 := 1.1;
    b: f32 := a;
    c: f32 := b * b - a / 3.0;
    println(c);
    println(c.sqrt());
}

use iter;
fn walk<a, b>(v: (&a u64[]), extra: (&b u64[])) -> iter::Iter<(&a u64)> {
    mut i = 0;
    return iter::from_fn(|| -> (&a u64)? {
        if i < v.len() + extra.len() { p := i; i = i + 1; return Some(&v[p]); }
        return None;
    });
}
