            }
            return bump(&mine, ctx, 1);
        })!);
    }
    while let Some(t) = threads.pop() {
        println(thread::join(t));
    }
    on_main := thread::with_current<u64>(|ctx: (&thread::Ctx)| -> u64 bump(&counter, ctx, 5))!;
    println(on_main);
}

