use thread;
use host;
fn show(e: thread::Error) -> unit {
    match e.what {
        Stack => { println("refused: stack {}", e.code); },
        Affinity => { println("refused: affinity {}", e.code); },
        Priority => { println("refused: priority {}", e.code); },
        Unsupported => { println("refused: unsupported {}", e.code); }
    }
}
fn main() {
    mut named = thread::config();
    named.name = "a-very-long-thread-name".text();
    t := thread::spawn<u8[]>(named, |ctx: (&thread::Ctx)| -> u8[] {
        return host::read_file("/proc/thread-self/comm");
    })!;
    print(thread::join(t));
    // Pinning to processor 0 is granted or refused by the OS; either way it is an answer.
    mut pinned = thread::config();
    pinned.affinity = Some(thread::cpus(u64[0]));
    match thread::spawn<u64>(pinned, |ctx: (&thread::Ctx)| -> u64 { return 1; }) {
        thread::Thread<u64>(p) => { println("pin answered {}", thread::join(p)); },
        thread::Error(e) => { println("pin answered {}", u64(e.code != 0)); }
    }
    mut nowhere = thread::config();
    nowhere.affinity = Some(thread::cpus(u64[1000]));
    match thread::spawn<u64>(nowhere, |ctx: (&thread::Ctx)| -> u64 { println("must not run"); return 1; }) {
        thread::Thread<u64>(p) => { println(thread::join(p)); },
        thread::Error(e) => { show(e); }
    }
    mut urgent = thread::config();
    // Priority 0 is not a realtime priority: the OS refuses it whoever asks.
    urgent.priority = thread::Priority::Realtime(0);
    match thread::spawn<u64>(urgent, |ctx: (&thread::Ctx)| -> u64 { return 1; }) {
        thread::Thread<u64>(p) => { println("realtime granted {}", thread::join(p)); },
        thread::Error(e) => { show(e); }
    }
    mut quiet = thread::config();
    quiet.priority = thread::Priority::Background;
    println(thread::join(thread::spawn<u64>(quiet, |ctx: (&thread::Ctx)| -> u64 { return 3; })!));
}

use thread;
use host;
struct Ticks { n: Atomic<u64> }
fn ticker(n: u64, c: (&Ticks)) -> u64 {
    for i in n {
        host::sleep_ms(10);
        c.n.fetch_add(1);
    }
    return n;
}
fn joiner(n: u64, c: (&Ticks)) -> u64 {
    t := thread::spawn<u64>(thread::config(), |ctx: (&thread::Ctx)| -> u64 { host::sleep_ms(200); return 5; })!;
    r := thread::join(t);
    // The timer task kept running on the scheduler while this task waited for the thread.
    assert(c.n.load() >= 5);
    return r;
}
fn body<s>(sc: (&s Scope<(&Ticks)>), c: (&Ticks)) -> u64 {
    a := spawn(sc, 30, ticker);
    b := spawn(sc, 0, joiner);
    return join(b) + join(a);
}
fn main() {
    ticks := Ticks { n: Atomic::new(0) };
    println(task_scope(&ticks, body));
}

