use thread;
use rc;
use host;
struct Shared { total: Mutex<u64>, entered: Atomic<u64> }
fn bad<a>(v: (&a mut u64), n: u64) -> u64 {
    *v += 1;
    w := u64[1];
    return w[n];
}
fn peek<a>(v: (&a mut u64), n: u64) -> u64 { return *v; }
fn main() {
    s := rc::arc_new(Shared { total: Mutex::new(0), entered: Atomic::new(0) });
    one := s.clone();
    t := thread::spawn<u64>(thread::config(), |ctx: (&thread::Ctx)| -> u64 {
        return one.get().total.lock_with(5, bad);
    })!;
    match thread::try_join(t) {
        TaskFailure(e) => { println("thread failed: {}", e.message); },
        u64(v) => { println(v); }
    }
    // The failed thread's stack was discarded with the lock held: the runtime released it and
    // poisoned it, so the next locker fails at lock_with (contained on its thread) and never gets in.
    two := s.clone();
    waiter := thread::spawn<u64>(thread::config(), |ctx: (&thread::Ctx)| -> u64 {
        got := two.get().total.lock_with(0, peek);
        two.get().entered.store(1);
        return got;
    })!;
    thread::detach(waiter);
    host::sleep_ms(200);
    println("second locker got in: {}", s.get().entered.load());
}

