struct Shared { m: Mutex<u64> }
// Process user + system time in clock ticks (1/100 s), from /proc/self/stat fields 14 and 15.
fn cpu_ticks() -> u64 {
    text := host::read_file("/proc/self/stat");
    mut i = 0;
    while text[i] != 41 {
        i += 1;
    }
    mut field = 2;
    mut total = 0;
    mut n = 0;
    while i < text.len() {
        c := text[i];
        if c == 32 {
            if (field == 14) || (field == 15) {
                total += n;
            }
            field += 1;
            n = 0;
        } else if (c >= 48) && (c <= 57) {
            n = n * 10 + u64(c - 48);
        }
        i += 1;
    }
    return total;
}
fn hold<a>(v: (&a mut u64), ms: u64) -> u64 {
    host::sleep_ms(ms);
    *v += 1;
    return *v;
}
fn bump<a>(v: (&a mut u64), by: u64) -> u64 {
    *v += by;
    return *v;
}
fn holder(n: u64, s: (&Shared)) -> u64 {
    return s.m.lock_with(300, hold);
}
fn waiter(n: u64, s: (&Shared)) -> u64 {
    host::sleep_ms(30);
    return s.m.lock_with(1, bump);
}
fn body<sc>(scope: (&sc Scope<(&Shared)>), s: (&Shared)) -> u64 {
    mut many = Task<u64>[];
    many.push(spawn(scope, 0, holder));
    for i in 8 {
        many.push(spawn(scope, i, waiter));
    }
    mut last = 0;
    while let Some(t) = many.pop() {
        r := join(t);
        if last < r { last = r; }
    }
    return last;
}
fn main() {
    s := Shared { m: Mutex::new(0) };
    before := cpu_ticks();
    start := host::now_ms();
    println(task_scope(&s, body));
    wall := host::now_ms() - start;
    used := (cpu_ticks() - before) * 10;
    // Eight waiters through a 300 ms hold: parked, they burn (almost) nothing.
    println((wall >= 300) && (used < 100));
}

