use thread;
use host;
fn threads_now() -> u64 {
    text := host::read_file("/proc/self/status");
    mut i = 0;
    // "Threads:\t" then the count.
    while i + 8 < text.len() {
        if (text[i] == 84) && (text[i + 1] == 104) && (text[i + 2] == 114) && (text[i + 7] == 58) {
            mut n = 0;
            mut j = i + 8;
            while (j < text.len()) && (text[j] != 10) {
                if (text[j] >= 48) && (text[j] <= 57) {
                    n = n * 10 + u64(text[j] - 48);
                }
                j += 1;
            }
            return n;
        }
        i += 1;
    }
    return 0;
}
fn joiner(n: u64, unused: u64) -> u64 {
    t := thread::spawn<u64>(thread::config(), |ctx: (&thread::Ctx)| -> u64 { host::sleep_ms(300); return 1; })!;
    return thread::join(t);
}
