    mut many = Task<u64>[];
    for i in 16 {
        many.push(spawn(sc, 0, joiner));
    }
    mut total = 0;
    while let Some(t) = many.pop() {
        total += join(t);
    }
    return total;
}
fn main() {
    // Counted from a thread of its own: a task's host::read_file would itself start a helper.
    probe := thread::spawn<u64>(thread::config(), |ctx: (&thread::Ctx)| -> u64 { host::sleep_ms(150); return threads_now(); })!;
    println(task_scope(0, body));
    seen := thread::join(probe);
    // Sixteen joins in flight: the joiners park, so the process holds the workers, the reactor and
    // the sixteen threads - not a helper thread per join on top.
    // main, the workers, the reactor, the scheduler's monitor, the probe and the sixteen threads.
    println(seen <= 1 + host::workers() + 1 + 1 + 1 + 16);
}

