use sync;
use time;
use host;
// One waiter on each primitive, its scope cancelled while it waits: a plain wait ends the task as
// Cancelled, a `_until` form answers Cancelled, and the cancelled scope re-raises nothing.
struct Shared { m: Mutex<u64>, c: sync::Condition, l: sync::Latch, b: sync::Barrier, s: sync::Semaphore, rw: sync::RwLock<u64>, out: Mutex<u64[]>, holding: Atomic<u64> }
fn note<a>(v: (&a mut u64[]), n: u64) -> u64 { v.push(n); return v.len(); }
fn total<a>(v: (&a mut u64[]), n: u64) -> u64 {
    mut t = 0;
    for i in v.len() {
        t += v[i];
    }
    return t;
}
fn on_condition(n: u64, s: (&Shared)) -> u64 {
    return s.c.wait_with(&s.m, 0, |v: (&u64), k: (&u64)| -> bool *v == 99, |v: (&mut u64), k: u64| -> u64 *v);
}
fn on_latch(n: u64, s: (&Shared)) -> u64 { s.l.wait(); return 1; }
fn on_barrier(n: u64, s: (&Shared)) -> u64 { s.b.wait(); return 1; }
fn on_semaphore(n: u64, s: (&Shared)) -> u64 { return s.s.acquire_with(1, 0, |k: u64| -> u64 k); }
fn on_sleep(n: u64, s: (&Shared)) -> u64 { time::sleep_ms(5000); return 1; }
fn on_try_sleep(n: u64, s: (&Shared)) -> u64 {
    match time::try_sleep_ms(5000) {
        time::WaitError(e) => { s.out.lock_with(10, note); },
        unit(u) => {}
    }
    return 0;
}
fn on_latch_until(n: u64, s: (&Shared)) -> u64 {
    match s.l.wait_until(time::now().after_ms(5000)) {
        time::WaitError(e) => {
            match e {
                Cancelled => { s.out.lock_with(20, note); },
                TimedOut => { s.out.lock_with(21, note); }
            }
        },
        unit(u) => {}
    }
    return 0;
}
fn on_rw_until(n: u64, s: (&Shared)) -> u64 {
    // Behind the holder for certain: the holder has the read lock before this asks to write.
    while s.holding.load() == 0 {
        host::sleep_ms(1);
    }
    match s.rw.write_until(time::now().after_ms(5000), 0, |v: (&mut u64), k: u64| -> u64 *v) {
        time::WaitError(e) => { s.out.lock_with(30, note); },
        u64(v) => {}
    }
    return 0;
}
fn holder(n: u64, s: (&Shared)) -> u64 {
    // Holds the read lock through the cancellation without waiting on anything cancellable, so the
    // writer below is certainly parked behind it when the scope is cancelled.
    return s.rw.read_with(0, |v: (&u64), k: u64| -> u64 { s.holding.store(1); until := host::now_ms() + 400; while host::now_ms() < until {} return *v; });
}
fn body<sc>(scope: (&sc Scope<(&Shared)>), s: (&Shared)) -> u64 {
    spawn(scope, 0, holder);
    spawn(scope, 0, on_condition);
    spawn(scope, 0, on_latch);
    spawn(scope, 0, on_barrier);
    spawn(scope, 0, on_semaphore);
    spawn(scope, 0, on_sleep);
    spawn(scope, 0, on_try_sleep);
    spawn(scope, 0, on_latch_until);
    spawn(scope, 0, on_rw_until);
    while s.holding.load() == 0 {
        host::sleep_ms(1);
    }
    host::sleep_ms(100);
    scope.cancel();
    return 0;
}
fn main() {
    s := Shared { m: Mutex::new(0), c: sync::condition(), l: sync::latch(1), b: sync::barrier(2), s: sync::semaphore(0), rw: sync::rwlock<u64>(5), out: Mutex::new(u64[]), holding: Atomic::new(0) };
    start := host::now_ms();
    println(task_scope(&s, body));
    println(host::now_ms() - start < 2000);
    println(s.out.lock_with(0, total));
}

