use sync;
use host;
// What a Cancelled outcome is: try_join reports it with kind 16; join re-raises it; and the scope
// that was cancelled does not re-raise the children it ended.
struct Shared { l: sync::Latch }
fn waits(n: u64, s: (&Shared)) -> u64 { s.l.wait(); return 1; }
fn inner<sc>(scope: (&sc Scope<(&Shared)>), s: (&Shared)) -> u64 {
    t := spawn(scope, 0, waits);
    host::sleep_ms(30);
    scope.cancel();
    match try_join(t) {
        TaskFailure(e) => { println("try_join: kind {} {}", e.kind, e.message); },
        u64(v) => { println(v); }
    }
    spawn(scope, 0, waits);
    return 7;
}
fn rejoin<sc>(scope: (&sc Scope<(&Shared)>), s: (&Shared)) -> u64 {
    t := spawn(scope, 0, waits);
    host::sleep_ms(30);
    scope.cancel();
    return join(t);
}
fn outer(n: u64, s: (&Shared)) -> u64 {
    return task_scope(s, rejoin);
}
fn top<sc>(scope: (&sc Scope<(&Shared)>), s: (&Shared)) -> u64 {
    match try_join(spawn(scope, 0, outer)) {
        TaskFailure(e) => { println("join re-raised: kind {}", e.kind); },
        u64(v) => { println(v); }
    }
    return 0;
}
fn main() {
    s := Shared { l: sync::latch(1) };
    println(task_scope(&s, inner));
    task_scope(&s, top);
}

