fn pass(f: Fn() -> u64) -> u64 { mut g = f; return run(g); }
fn run(f: Fn() -> u64) -> u64 { return f(); }
fn main() {
    mut q = Q { items: (Fn() -> u64)[] };
    n := 20;
    keep(&mut q, || -> u64 n + 1);
