// A slice's data and len held in registers (optimize.grl `desc_choose`): an index past the end
// still fails as the accessor would, naming the index and the length.
fn sum_upto(x: (&[u64]), n: u64) -> u64 {
    mut total = 0;
    mut i = 0;
    while i <= n {
        total = total + x[i];
        i += 1;
    }
    return total;
}
