}

// A store into a u8[] is a bounds check and one byte store (optimize.grl `leaf_expansion` 55); an index past the end still fails naming the
// index and the length.
fn mark<a>(v: (&a mut u8[]), step: u64) -> u64 {
    mut i = 0;
    mut n = 0;
    while i < v.len() {
        v[i] = 7;
        n += 1;
        i += step;
    }
    return n;
}
