module derives_eq_record;
struct Inner { n: u64 }
@derive(Eq)
struct Tagged { n: u64, tag: string }
@derive(Eq)
struct Outer { left: Tagged, other: u64 }
fn main() {
    a := Outer { left: Tagged { n: 1, tag: "x".text() }, other: 2 };
    b := Outer { left: Tagged { n: 1, tag: "x".text() }, other: 2 };
    c := Outer { left: Tagged { n: 1, tag: "y".text() }, other: 2 };
    println("{} {} {}", a == b, a == c, a != c);
}

module derives_ord_record;
@derive(Eq, Ord)
struct P { x: u64, y: u64 }
fn main() {
    a := P { x: 1, y: 5 };
    b := P { x: 1, y: 6 };
    c := P { x: 2, y: 0 };
    println("{} {} {} {}", a < b, b < a, a < c, c < a);
    println("{} {}", a.less(&a), a <= b);
}

module derives_hash_record;
use hash;
@derive(Eq, Hash)
struct P { x: u64, name: string }
fn fingerprint<a>(v: (&a P)) -> u64 {
    mut st = hash::hasher(3, 5);
    hash::Hash::hash(v, &mut st);
    return hash::finish(st);
}
fn main() {
    a := P { x: 1, name: "ada".text() };
    b := P { x: 1, name: "ada".text() };
    c := P { x: 1, name: "bob".text() };
    println("{} {} {}", a == b, fingerprint(&a) == fingerprint(&b), fingerprint(&a) == fingerprint(&c));
}

module derives_clone_record;
@derive(Clone, Eq, Hash)
struct P { x: u64, name: string }
@derive(Clone, Eq)
struct Q { p: P, n: u64 }
fn main() {
    a := P { x: 7, name: "ada".text() };
    b := a.clone();
    println("{} {} {}", b.x, b.name, a == b);
    q := Q { p: a, n: 1 };
    r := q.clone();
    println("{} {} {}", r.n, r.p.name, q == r);
}

