use host;
use net;
use tls;

// TLS against a loopback `openssl s_server` holding a certificate generated here, which is the
// acceptance test for verification: the same call must be REFUSED while the certificate is
// untrusted and ACCEPTED once it is the configured anchor. A layer that spoke TLS without checking
// would pass only the second half.

fn shell(script: string) -> u64 {
    mut argv = u8[][];
    argv.push(view("sh").copy());
    argv.push(view("-c").copy());
    argv.push(view(script).copy());
    return host::command(argv);
}

fn port_text(number: u64) -> string {
    mut digits = u8[];
    mut rest = number;
    while rest > 0 {
        digits.push(u8(48 + rest % 10));
        rest = rest / 10;
    }
    mut out = u8[];
    mut i = digits.len();
    while i > 0 {
        i -= 1;
        out.push(digits[i]);
    }
    return out.text();
}

fn stop_server() -> u64 {
    data := host::read_file(view("pid"));
    mut pid = u8[];
    for b in data {
        if b >= 48 {
            if b <= 57 {
                pid.push(b);
            }
        }
    }
    if pid.len() == 0 {
        return 0;
    }
    mut argv = u8[][];
    argv.push(view("kill").copy());
    argv.push(pid);
    return host::command(argv);
}

// Whether s_server is accepting on `port`: waited for on a deadline, not a count of tries, so a
// loaded host that takes seconds to start it still passes; a server that already exited (the port
// was taken) answers at once.
fn listening(port: u64) -> bool {
    deadline := host::now_ms() + 30000;
    while host::now_ms() < deadline {
        match net::connect("127.0.0.1", port) {
            stream: net::TcpStream => {
                stream.close();
                return true;
            },
            error: io::Error => {
                if shell("kill -0 $(cat pid) 2>/dev/null") != 0 {
                    return false;
                }
                host::sleep_ms(50);
            }
        }
    }
    return false;
}

fn is_io<a>(error: (&a tls::Error)) -> bool {
    match error {
        Io(code) => { return true; },
        _ => { return false; }
    }
}

// A transport failure means the server is not accepting yet (it serves one connection at a time),
// so it is retried until a deadline; anything else is final.
fn open_client(client: (&tls::TlsClient), port: u64) -> tls::TlsStream |? tls::Error {
    deadline := host::now_ms() + 30000;
    mut last: tls::Error = tls::Error::Closed;
    while host::now_ms() < deadline {
        match client.connect("127.0.0.1", port, "127.0.0.1") {
            stream: tls::TlsStream => {
                return stream;
            },
            error: tls::Error => {
                if !is_io(&error) {
                    return error;
                }
                last = error;
                host::sleep_ms(50);
            }
        }
    }
    return last;
}

fn contains<a, b>(text: (&a [u8]), needle: (&b [u8])) -> bool {
    if needle.len() > text.len() {
        return false;
    }
    mut i: u64 = 0;
    while i + needle.len() <= text.len() {
        mut matched = 1;
        mut j: u64 = 0;
        while j < needle.len() {
            if text[i + j] != needle[j] {
                matched = 0;
            }
            j += 1;
        }
        if matched == 1 {
            return true;
        }
        i += 1;
    }
    return false;
}

fn main() -> u64 {
    // One self-signed certificate for 127.0.0.1, generated now: it is its own trust anchor.
    made := shell("openssl req -x509 -newkey rsa:2048 -noenc -keyout key.pem -out cert.pem -days 1 -subj /CN=127.0.0.1 -addext subjectAltName=IP:127.0.0.1 2>gen.log");
    if made != 0 {
        println("tls: skipped, no usable openssl CLI");
        return 0;
    }
    // A port this process never bound: a port it binds and releases can be handed back to its own
    // client socket as the local port, which makes the connection useless.
    mut port: u64 = 0;
    mut candidate: u64 = 24131;
    while candidate < 24171 {
        started := shell("openssl s_server -accept " + port_text(candidate) + " -cert cert.pem -key key.pem -rev -quiet > server.log 2>&1 & echo $! > pid");
        if listening(candidate) {
            port = candidate;
            break;
        }
        stop_server();
        candidate += 1;
    }
    if port == 0 {
        println("tls: skipped, no port for s_server");
        return 0;
    }

    // 1. The system store does not contain this certificate: refused.
    mut plain = tls::config();
    mut system_only = tls::client(&plain)!;
    match open_client(&system_only, port) {
        stream: tls::TlsStream => {
            println("untrusted: accepted");
            stream.close();
        },
        error: tls::Error => {
            println("untrusted: refused");
            println(error.is_verify());
        }
    }

    // 2. The same connection with that certificate trusted: accepted, and the address verified.
    mut trusting = tls::config();
    trusting.set_ca_file("cert.pem");
    mut client = tls::client(&trusting)!;
    mut stream = open_client(&client, port)!;
    println(stream.version());
    println(stream.peer_subject());

    // 3. 3000 bytes in, the server's `-rev` answer out: byte for byte.
    mut line = u8[];
    mut i = 0;
    while i < 3000 {
        line.push(u8(97 + i % 26));
        i += 1;
    }
    // `-rev` answers a line, so the payload ends with the newline that releases it.
    line.push(10);
    stream.write_all(view(line))!;
    mut echoed = u8[];
    while echoed.len() < line.len() {
        mut chunk = u8[0; 4096];
        count := stream.read(&mut chunk)!;
        if count == 0 {
            break;
        }
        for k in count {
            echoed.push(chunk[k]);
        }
    }
    mut reversed = 1;
    mut j = 0;
    while j < 3000 {
        if echoed[j] != line[2999 - j] {
            reversed = 0;
        }
        j += 1;
    }
    println(echoed.len());
    println(reversed);

    // 4. close_notify out, then the peer's abrupt end is the truncation class, not a clean 0.
    stream.shutdown()!;
    mut tail = u8[0; 64];
    match stream.read(&mut tail) {
        count: u64 => {
            println(count);
        },
        error: tls::Error => {
            println(error.is_closed());
        }
    }
    stream.close();
    // The server logs the close it received: proof the close_notify reached and parsed at the peer.
    host::sleep_ms(300);
    log := host::read_file(view("server.log"));
    println(contains(view(log), view("CONNECTION CLOSED")));

    // 5. A trust store that cannot be loaded is a refusal, not an unverified connection.
    mut broken = tls::config();
    broken.set_ca_file("no-such-ca.pem");
    match tls::client(&broken) {
        ready: tls::TlsClient => {
            println("missing ca: built");
        },
        error: tls::Error => {
            println(error.is_no_trust_store());
        }
    }
    stop_server();
    return 0;
}

use host;
use net;
use tls;

// A real handshake against example.com: the negotiated version, the ALPN protocol the server chose
// and the certificate subject, all of which only exist if the chain verified. The address comes
// from a resolver in a child process because the runtime has no name lookup; an offline host skips.

fn shell(script: string) -> u64 {
    mut argv = u8[][];
    argv.push(view("sh").copy());
    argv.push(view("-c").copy());
    argv.push(view(script).copy());
    return host::command(argv);
}

fn starts_with<a, b>(text: (&a [u8]), prefix: (&b [u8])) -> bool {
    if text.len() < prefix.len() {
        return false;
    }
    mut i: u64 = 0;
    while i < prefix.len() {
        if text[i] != prefix[i] {
            return false;
        }
        i += 1;
    }
    return true;
}

fn trimmed<a>(data: (&a [u8])) -> string {
    mut out = u8[];
    for b in data {
        if b != 10 {
            if b != 13 {
                out.push(b);
            }
        }
    }
    return out.text();
}

fn main() -> u64 {
    if shell("getent ahostsv4 example.com | head -1 | cut -d' ' -f1 > address.txt 2>/dev/null") != 0 {
        println("tls: skipped, no resolver");
        return 0;
    }
    address := trimmed(view(host::read_file(view("address.txt"))));
    if address.len() < 7 {
        println("tls: skipped, example.com did not resolve");
        return 0;
    }
    // One context, two connections: the negotiated version and the protocol the server picks.
    mut picked = tls::config();
    picked.add_alpn("h2,http/1.1");
    picked.set_min_version(tls::VERSION_TLS13);
    match tls::client(&picked) {
        ready: tls::TlsClient => {
            mut client = ready;
            mut reached = 0;
            match client.connect(address, 443, "example.com") {
                stream_value: tls::TlsStream => {
                    mut s = stream_value;
                    reached = 1;
                    println(s.version());
                    println(s.alpn());
                    println(s.peer_subject());
                    s.close();
                },
                error: tls::Error => {
                    println("tls: skipped, example.com unreachable");
                }
            }
            if reached == 0 {
                return 0;
            }
            // A second connection that speaks HTTP/1.1, so the request really crosses the stream.
            second := trimmed(view(host::read_file(view("address.txt"))));
            mut http = tls::config();
            http.add_alpn("http/1.1");
            mut web = tls::client(&http)!;
            mut s2 = web.connect(second, 443, "example.com")!;
            println(s2.alpn());
            mut request: string = "GET / HTTP/1.0\r\nHost: example.com\r\n\r\n";
            s2.write_all(view(request))!;
            mut body = u8[];
            loop {
                mut chunk = u8[0; 4096];
                match s2.read(&mut chunk) {
                    count: u64 => {
                        if count == 0 {
                            break;
                        }
                        for i in count {
                            body.push(chunk[i]);
                        }
                    },
                    error: tls::Error => {
                        // A peer that ends without a close_notify is the truncation class; the
                        // bytes that did arrive are still the response.
                        break;
                    }
                }
            }
            println(starts_with(view(body), view("HTTP/1.")));
            s2.close();
        },
        error: tls::Error => {
            println("tls: skipped, no system trust store");
        }
    }
    return 0;
}

use tls;

// A TLS context with no trust anchors verifies nothing, so it must not be buildable: the system
// store here is empty (SSL_CERT_FILE and SSL_CERT_DIR point at nothing) and the explicit CA file
// does not exist. Both are a refusal, not an unverified connection.
fn main() -> u64 {
    mut plain = tls::config();
    match tls::client(&plain) {
        ready: tls::TlsClient => {
            println("system store: built");
        },
        error: tls::Error => {
            println(error.is_no_trust_store());
        }
    }
    mut missing = tls::config();
    missing.set_ca_file("definitely-not-here.pem");
    match tls::client(&missing) {
        ready: tls::TlsClient => {
            println("missing ca: built");
        },
        error: tls::Error => {
            println(error.is_no_trust_store());
        }
    }
    return 0;
}

