fn mapv<T, U, F: FnMut(T) -> U>(v: T[], f: F) -> U[] {
    mut g = f;
    mut out = U[];
    mut src = v;
    src.reverse();
    while src.len() != 0 { out.push(g(src.pop()!)); }
    return out;
}
