fn bump(s: &mut [u64], depth: u64) {
    if (s.len() < 2) || (depth == 0) {
        for i in s.len() {
            s[i] += depth + 1;
        }
        return;
    }
    mid := s.len() / 2;
    l, r := split_at_mut(s, mid);
    bump(l, depth - 1);
    bump(r, depth - 1);
}
