struct Box1<T> { v: T }
fn with_lock<a, T, C, R: Owned, F: FnMut((&mut T), C) -> R>(m: (&a mut Box1<T>), ctx: C, f: F) -> R { mut g = f; return g(&mut m.v, ctx); }
fn rem<a, b>(v: (&a mut u64[]), k: (&b u64)) -> u64 { return v.len(); }
fn go<a, b>(m: (&a mut Box1<u64[]>), key: (&b u64)) -> u64 { return with_lock(&mut m, 0, |v: (&mut u64[]), unused: u64| -> u64 rem(v, key)); }
fn main() { mut m = Box1 { v: u64[1] }; k := 5; println(go(&mut m, &k)); }

