// host::chmod sets a file's permission bits (0 or a positive errno), which is how the build store
// gives an image it restores its execute bits.
fn main() {
    host::write_file(view("chmod.bin"), view("x"));
    println(host::chmod(view("chmod.bin"), 493));
    st := host::stat(view("chmod.bin"), 1);
    println(st[3] & 511);
    println(host::chmod(view("chmod.bin"), 420));
    again := host::stat(view("chmod.bin"), 1);
    println(again[3] & 511);
    println(host::chmod(view("no-such-file.bin"), 493));
    host::remove(view("chmod.bin"), 0);
}

fn step(p: &mut [f32], v: &[f32]) {
    for i in p.len() {
        p[i] = p[i] + v[i] * 0.5;
    }
}
fn main() {
    n := 10000;
    mut pos = f32[0.0; n];
    mut vel = f32[0.0; n];
    mut life = u32[0; n];
    for i in n {
        vel[i] = f32(i % 7);
    }
    parallel_for_zip(256, step, &mut pos[0: n], &vel[0: n]);
    scale: f32 = 2.0;
    parallel_for_zip(100, |p: &mut [f32], v: &[f32], l: &mut [u32]| -> unit {
        for i in p.len() {
            p[i] = p[i] * scale + v[i];
            l[i] = l[i] + 1;
        }
    }, &mut pos[0: n], &vel[0: n], &mut life[0: n]);
    mut t: f32 = 0.0;
    mut lt = 0;
    for i in n {
        t = t + pos[i];
        lt += u64(life[i]);
    }
    println("{} {}", t, lt);
}

use pool;
fn main() {
    n := 5000;
    mut pos = f32[0.0; n];
    mut vel = f32[1.0; n];
    mut life = u32[3; n];
    dt: f32 = 0.5;
    for frame in 4 {
        pool::zip3(&mut pos[0: n], &vel[0: n], &mut life[0: n], 512, |p: &mut [f32], v: &[f32], l: &mut [u32]| -> unit {
            for i in p.len() {
                p[i] = p[i] + v[i] * dt;
                if l[i] > 0 {
                    l[i] = l[i] - 1;
                }
            }
        });
    }
    pool::zip2(&mut vel[0: n], &pos[0: n], 700, |v: &mut [f32], p: &[f32]| -> unit {
        for i in v.len() {
            v[i] = p[i] * 2.0;
        }
    });
    mut sp: f32 = 0.0;
    mut sl = 0;
    for i in n {
        sp = sp + vel[i];
        sl += u64(life[i]);
    }
    println("{} {}", sp, sl);
}

pub fn zip2<A: Send, B: Share, F: Fn<Share>((&mut [A]), (&[B])) -> unit>(a: (&mut [A]), b: (&[B]), grain: u64 where grain > 0, f: F) -> unit {
    parallel_for_zip(grain, f, a, b);
}
fn main() {
    mut a = f32[0.0; 8];
    b := f32[1.0; 8];
    zip2(&mut a[0: 8], &b[0: 8], 3, |p: &mut [f32], v: &[f32]| -> unit {
        for i in p.len() {
            p[i] = v[i] * 2.0;
        }
    });
    println(a);
}

