fn twice(v: u64[]) -> u64 {
    mut w = v;
    mut s = 0;
    for i in w.len() {
        w[i] = wrapping_mul(w[i], 2);
        s = wrapping_add(s, w[i]);
    }
    return s;
}
fn main() {
    println(twice(u64[1, 2, 3]));
}

fn total(v: &u64[]) -> u64 {
    n := v.len();
    mut s = 0;
    mut i = 0;
    while i < n {
        s = wrapping_add(s, v[i]);
        i += 1;
    }
    return s;
}
