fn product(n0: u64) -> u64 {
    n: u64 := 8;
    mut a = u64[];
    mut c = u64[];
    for i in n * n {
        a.push(i % 5);
        c.push(0);
    }
    for i in n {
        for j in n {
            mut s: u64 = 0;
            for k in n {
                s = s + a[i * n + k] * a[k * n + j];
            }
            c[i * n + j] = s;
        }
    }
    mut t: u64 = n0;
    for i in n * n {
        t = t + c[i];
    }
    return t;
}
fn main() {
    println(product(0));
}

fn apply(f: Fn(u64) -> u64, x: u64) -> u64 {
    return f(x) + f(x + 1);
}
fn each(n: u64, f: FnMut(u64) -> unit) -> unit {
    mut call = f;
    for i in n { call(i); }
}
fn main() -> u64 {
    k := host::argc();
    v := u64[10, 20, 30];
    mut total = 0;
    for i in 1000 {
        owned := u64[i, i + 1];
        r := &v;
        total += apply(|x: u64| -> u64 x + r[0] + owned.len() + k, i);
    }
    mut seen = 0;
    each(5, |i: u64| { seen += i * k; });
    println("{} {} {}", total, seen, v.len());
    return 0;
}
